// =========================================================
// FILTRAR CANDIDATOS PARA CONTROL POSTGRESQL - CAT
// =========================================================
//
// PostgreSQL es la autoridad para decidir posteriormente:
//
// - CREATED
// - ALREADY_PROCESSING
// - ALREADY_COMPLETED
// - ALREADY_ERROR
// - ALREADY_CANCELLED
//
// Este nodo solamente:
// 1. valida candidatos;
// 2. excluye archivos historicos anteriores al corte;
// 3. ordena los candidatos.
//
// NO consulta archivos_procesados_cat.json.
// NO controla reintentos.
// NO decide si un archivo ya fue procesado.
// =========================================================

const FECHA_CORTE_PG =
  new Date("2026-09-21T00:00:00-06:00");

// =========================================================
// FUNCIONES
// =========================================================

function cleanText(value) {
  return String(value ?? "").trim();
}

function obtenerFechaArchivo(archivo) {
  const valores = [
    archivo.last_write_time_utc,
    archivo.last_write_time
  ];

  for (const valor of valores) {
    const texto = cleanText(valor);

    if (!texto) {
      continue;
    }

    const fecha = new Date(texto);

    if (!Number.isNaN(fecha.getTime())) {
      return fecha;
    }
  }

  // Fallback si solamente existe YYYY-MM-DD.
  const fechaIso = cleanText(
    archivo.fecha_archivo_iso
  );

  if (fechaIso) {
    const fecha = new Date(
      `${fechaIso}T00:00:00-06:00`
    );

    if (!Number.isNaN(fecha.getTime())) {
      return fecha;
    }
  }

  return null;
}

function esCandidatoValido(archivo) {
  if (
    archivo.tipo_resultado !==
    "ARCHIVO_DETECTADO"
  ) {
    return false;
  }

  if (
    archivo.procesar_automaticamente !== true
  ) {
    return false;
  }

  if (!cleanText(archivo.file_path)) {
    return false;
  }

  if (!cleanText(archivo.file_name)) {
    return false;
  }

  return true;
}

// =========================================================
// FILTRAR
// =========================================================

const candidatos = $input
  .all()
  .map(item => item.json)

  .filter(esCandidatoValido)

  .map(archivo => {
    const fechaArchivo =
      obtenerFechaArchivo(archivo);

    return {
      archivo,
      fechaArchivo
    };
  })

  .filter(({ fechaArchivo }) => {

    // Si no podemos determinar una fecha confiable,
    // no se procesa automaticamente.
    if (!fechaArchivo) {
      return false;
    }

    // Todo lo anterior al 21/09/2026
    // se considera historico.
    return fechaArchivo >= FECHA_CORTE_PG;
  });

// =========================================================
// ORDENAR
// =========================================================
//
// Procesamos primero los candidatos mas antiguos dentro
// del universo posterior al corte.
//
// Esto evita que un archivo pendiente pueda quedarse
// permanentemente detras de archivos mas recientes.
// =========================================================

candidatos.sort((a, b) => {
  return (
    a.fechaArchivo.getTime() -
    b.fechaArchivo.getTime()
  );
});

// =========================================================
// SALIDA
// =========================================================

return candidatos.map(
  ({ archivo, fechaArchivo }) => ({
    json: {
      ...archivo,

      control_procesado: "POSTGRESQL",

      fecha_corte_pg:
        FECHA_CORTE_PG.toISOString(),

      fecha_archivo_control:
        fechaArchivo.toISOString()
    }
  })
);

