// =========================================================
// NORMALIZAR DATOS CAT
// Compatible con:
// - CAT normal: 1 remisión por artículo
// - CAT Torreón: 1 remisión por OC, con varios artículos
// =========================================================

const MODO_ESTRICTO_CATALOGO = true;
const MODO_ESTRICTO_TORREON_FINANZAS = false;
const IVA_TORREON = 0.16;

// =========================================================
// FUNCIONES GENERALES
// =========================================================

function cleanText(value) {
  return String(value ?? "").trim();
}

function cleanMultiline(value) {
  return cleanText(value)
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n")
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n[ \t]+/g, "\n")
    .trim();
}

function normalizeText(value) {
  return cleanText(value)
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toUpperCase()
    .replace(/\s+/g, " ")
    .trim();
}

function normalizeCompact(value) {
  return normalizeText(value).replace(/[^A-Z0-9]/g, "");
}

function normalizeCode(value) {
  return cleanText(value)
    .toUpperCase()
    .replace(/\s+/g, "")
    .trim();
}

function normalizeTipoEmpaque(value) {
  return normalizeText(value)
    .replace(/\s+POR\s+/g, "_")
    .replace(/[\/\-\s]+/g, "_")
    .replace(/_+/g, "_")
    .replace(/^_+|_+$/g, "");
}

function getFirstExisting(...values) {
  for (const value of values) {
    const text = cleanText(value);

    if (text !== "") {
      return value;
    }
  }

  return "";
}

function rowToArray(json) {
  if (Array.isArray(json)) return json;
  if (Array.isArray(json.row)) return json.row;
  if (Array.isArray(json.data)) return json.data;

  const keys = Object.keys(json);

  const numericKeys = keys
    .filter(key => /^\d+$/.test(key))
    .sort((a, b) => Number(a) - Number(b));

  if (numericKeys.length > 0) {
    return numericKeys.map(key => json[key]);
  }

  const emptyKeys = keys
    .filter(key => key === "__EMPTY" || /^__EMPTY_\d+$/.test(key))
    .sort((a, b) => {
      const getIndex = key => {
        if (key === "__EMPTY") return 0;
        return Number(key.replace("__EMPTY_", ""));
      };

      return getIndex(a) - getIndex(b);
