  return makeKey(clienteGrupo, plantaCodigo, subplantaCodigo, codigoExcel);
}

function makeProductKeyRaw(clienteGrupo, plantaCodigo, subplantaCodigo, codigoExcel) {
  return makeKeyRaw(clienteGrupo, plantaCodigo, subplantaCodigo, codigoExcel);
}

function isNo(value) {
  const text = normalizeText(value);
  return text === "NO" || text === "N";
}

function esEtiquetaNoProducto(codigo, descripcion, row = []) {
  const textoCodigo = normalizeCompact(codigo);
  const textoDescripcion = normalizeCompact(descripcion);
  const textoBase = normalizeCompact(`${codigo} ${descripcion}`);
  const textoFila = normalizeCompact(Array.isArray(row) ? row.join(" ") : "");

  if (!textoFila) return true;

  const etiquetasCompactas = [
    "CODIGO",
    "DESCRIPCION",
    "TOTAL",
    "SUBTOTAL",
    "CONSOLIDAR",
    "FECHADEENTREGA",
    "TRANSPORTE",
    "SOLICITADOPOR",
    "VALORDEVENTA",
    "VALORFACTURA",
    "METODODEPAGO",
    "FORMADEPAGO",
    "LUGARDEEXPEDICION",
    "IMPORTECONLETRA",
    "MONEDA",
    "TIPODECAMBIO",
    "TASADECONVERSION",
    "TC",
    "OBSERVACIONES",
    "NOTAS"
  ];

  const textosARevisar = [
    textoCodigo,
    textoDescripcion,
    textoBase,
    textoFila
  ];

  return textosARevisar.some(texto =>
    etiquetasCompactas.some(etiqueta =>
      texto === etiqueta ||
      texto.startsWith(etiqueta)
    )
  );
}

