function excelDateToString(value) {
  if (value === undefined || value === null) return "";

  if (value instanceof Date && !isNaN(value.getTime())) {
    const dd = String(value.getDate()).padStart(2, "0");
    const mm = String(value.getMonth() + 1).padStart(2, "0");
    const yyyy = value.getFullYear();

    return `${dd}/${mm}/${yyyy}`;
  }

  const text = cleanText(value);

  if (text === "") return "";
  if (text === "0") return "";

  const numberValue = Number(text);

  if (!isNaN(numberValue) && numberValue > 20000 && numberValue < 70000) {
    const excelEpoch = new Date(Date.UTC(1899, 11, 30));
    const date = new Date(excelEpoch.getTime() + numberValue * 86400000);

    const dd = String(date.getUTCDate()).padStart(2, "0");
    const mm = String(date.getUTCMonth() + 1).padStart(2, "0");
    const yyyy = date.getUTCFullYear();

    return `${dd}/${mm}/${yyyy}`;
  }

  return text;
}

function todayDdMmYyyyDash() {
  const now = new Date();

  const dd = String(now.getDate()).padStart(2, "0");
  const mm = String(now.getMonth() + 1).padStart(2, "0");
  const yyyy = now.getFullYear();

  return `${dd}-${mm}-${yyyy}`;
}

function parseNumber(value) {
  if (value === undefined || value === null) return null;

  let text = cleanText(value);

  if (text === "") return null;
  if (text === "-") return null;

  text = text
    .replace(/\$/g, "")
    .replace(/USD/gi, "")
    .replace(/MXN/gi, "")
    .replace(/\s+/g, "")
    .replace(/,/g, "");

  const numberValue = Number(text);

  if (isNaN(numberValue)) return null;

  return numberValue;
}

function buscarValorPorEtiqueta(rows, etiquetas) {
  const etiquetasNorm = etiquetas.map(etiqueta => normalizeCompact(etiqueta));

  for (let rowIndex = 0; rowIndex < rows.length; rowIndex++) {
    const row = rows[rowIndex];

    for (let col = 0; col < row.length; col++) {
      const cellRaw = cleanText(row[col]);
      const cellNorm = normalizeCompact(cellRaw);

      if (!cellNorm) continue;

      for (const etiqueta of etiquetasNorm) {
        if (cellNorm === etiqueta || cellNorm.startsWith(etiqueta)) {
          const despuesDeDosPuntos = cellRaw.split(":").slice(1).join(":").trim();

          if (despuesDeDosPuntos && parseNumber(despuesDeDosPuntos) !== null) {
            return despuesDeDosPuntos;
          }

          for (let offset = 1; offset <= 4; offset++) {
            const posibleValorDerecha = cleanText(row[col + offset]);

            if (posibleValorDerecha && parseNumber(posibleValorDerecha) !== null) {
              return posibleValorDerecha;
            }
          }

          for (let rowOffset = 1; rowOffset <= 4; rowOffset++) {
            const rowAbajo = rows[rowIndex + rowOffset];

            if (!rowAbajo) continue;

            const posibleValorAbajo = cleanText(rowAbajo[col]);

            if (posibleValorAbajo && parseNumber(posibleValorAbajo) !== null) {
              return posibleValorAbajo;
            }

            for (let colOffset = 1; colOffset <= 3; colOffset++) {
              const posibleValorDiagonal = cleanText(rowAbajo[col + colOffset]);

              if (posibleValorDiagonal && parseNumber(posibleValorDiagonal) !== null) {
                return posibleValorDiagonal;
              }
            }
          }
        }
      }
    }
  }

  return "";
}

function hasCantidad(value) {
  const numberValue = parseNumber(value);

  if (numberValue === null) return false;
  if (numberValue <= 0) return false;

  return true;
}

function parseCantidad(value) {
  const numberValue = parseNumber(value);

  if (numberValue === null || numberValue <= 0) {
    return null;
  }

  return numberValue;
}

function formatQuantity(value) {
  const numberValue = Number(value);

  if (isNaN(numberValue)) return "";

  if (Number.isInteger(numberValue)) {
    return String(numberValue);
  }

  return String(numberValue).replace(/\.?0+$/, "");
}

function formatQuantityTorreon(value) {
  const numberValue = Number(value);

  if (isNaN(numberValue)) return "";

  return numberValue.toLocaleString("en-US", {
    minimumFractionDigits: 4,
    maximumFractionDigits: 4
  });
}

function formatNumber(value, decimals = 2) {
  if (value === undefined || value === null || isNaN(Number(value))) return "";

  return Number(value).toLocaleString("en-US", {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals
  });
}

function formatCurrency(value, decimals = 2) {
  if (value === undefined || value === null || isNaN(Number(value))) return "";

  return `$${formatNumber(value, decimals)}`;
}

function formatTipoCambio(value) {
  const numberValue = parseNumber(value);

  if (numberValue === null) return "";

  return `$${numberValue.toLocaleString("en-US", {
    minimumFractionDigits: 4,
    maximumFractionDigits: 4
  })}`;
}

