// =========================================================
// IMPORTE EN LETRA SIMPLE PARA USD
// =========================================================

function unidades(n) {
  const map = [
    "",
    "UNO",
    "DOS",
    "TRES",
    "CUATRO",
    "CINCO",
    "SEIS",
    "SIETE",
    "OCHO",
    "NUEVE",
    "DIEZ",
    "ONCE",
    "DOCE",
    "TRECE",
    "CATORCE",
    "QUINCE",
    "DIECISÉIS",
    "DIECISIETE",
    "DIECIOCHO",
    "DIECINUEVE"
  ];

  return map[n] || "";
}

function decenas(n) {
  if (n < 20) return unidades(n);

  const d = Math.floor(n / 10);
  const u = n % 10;

  const map = {
    2: "VEINTE",
    3: "TREINTA",
    4: "CUARENTA",
    5: "CINCUENTA",
    6: "SESENTA",
    7: "SETENTA",
    8: "OCHENTA",
    9: "NOVENTA"
  };

  if (d === 2 && u > 0) {
    return `VEINTI${unidades(u).toLowerCase()}`.toUpperCase();
  }

  if (u === 0) return map[d];

  return `${map[d]} Y ${unidades(u)}`;
}

function centenas(n) {
  if (n < 100) return decenas(n);

  const c = Math.floor(n / 100);
  const r = n % 100;

  if (n === 100) return "CIEN";

  const map = {
    1: "CIENTO",
    2: "DOSCIENTOS",
    3: "TRESCIENTOS",
    4: "CUATROCIENTOS",
    5: "QUINIENTOS",
    6: "SEISCIENTOS",
    7: "SETECIENTOS",
    8: "OCHOCIENTOS",
    9: "NOVECIENTOS"
  };

  if (r === 0) return map[c];

  return `${map[c]} ${decenas(r)}`;
}

function enteroALetras(n) {
  n = Math.floor(Number(n));

  if (n === 0) return "CERO";
  if (n < 1000) return centenas(n);

  if (n < 1000000) {
    const miles = Math.floor(n / 1000);
    const resto = n % 1000;

    let textoMiles = "";

    if (miles === 1) {
      textoMiles = "MIL";
    } else {
      textoMiles = `${centenas(miles)} MIL`;
    }

    if (resto === 0) return textoMiles;

    return `${textoMiles} ${centenas(resto)}`;
  }

  const millones = Math.floor(n / 1000000);
  const resto = n % 1000000;

  let textoMillones = "";

  if (millones === 1) {
    textoMillones = "UN MILLÓN";
  } else {
    textoMillones = `${enteroALetras(millones)} MILLONES`;
  }

  if (resto === 0) return textoMillones;

  return `${textoMillones} ${enteroALetras(resto)}`;
}

function importeUsdALetras(value) {
  if (value === undefined || value === null || isNaN(Number(value))) return "";

  const total = Number(value);
  const entero = Math.floor(total);
  const centavos = Math.round((total - entero) * 100);
  const centavosText = String(centavos).padStart(2, "0");

  return `${enteroALetras(entero)} DÓLARES ${centavosText}/100 USD`;
}

