function objectValuesSafe(value) {
  if (!value || typeof value !== "object") return [];
  if (Array.isArray(value)) return value;
  return Object.values(value);
}

function buscarEnMapa(mapa, keys) {
  if (!mapa || typeof mapa !== "object") return null;

  for (const key of keys) {
    if (mapa[key]) return mapa[key];
  }

  return null;
}

function buscarProducto(productosMap, contexto, codigoExcel) {
  const clienteGrupo = contexto.cliente_grupo;
  const plantaCodigo = contexto.planta_codigo;
  const subplantaCodigo = contexto.subplanta_codigo || "";

  const keys = [
    makeProductKey(clienteGrupo, plantaCodigo, subplantaCodigo, codigoExcel),
    makeProductKeyRaw(clienteGrupo, plantaCodigo, subplantaCodigo, codigoExcel),

    makeProductKey(clienteGrupo, plantaCodigo, "", codigoExcel),
    makeProductKeyRaw(clienteGrupo, plantaCodigo, "", codigoExcel)
  ];

  const exacto = buscarEnMapa(productosMap, keys);

  if (exacto) return exacto;

  const candidatos = objectValuesSafe(productosMap).filter(producto => {
    const mismoCliente =
      normalizeText(producto.cliente_grupo) === normalizeText(clienteGrupo);

    const mismaPlanta =
      normalizeText(producto.planta_codigo) === normalizeText(plantaCodigo);

    const mismoCodigo =
      normalizeCode(producto.codigo_excel) === normalizeCode(codigoExcel);

    const subProducto = normalizeText(producto.subplanta_codigo || "");
    const subContexto = normalizeText(subplantaCodigo || "");

    const mismaSubplanta =
      subContexto === "" ||
      subProducto === subContexto ||
      subProducto === "";

    return mismoCliente && mismaPlanta && mismoCodigo && mismaSubplanta;
  });

  if (candidatos.length === 1) return candidatos[0];

  if (candidatos.length > 1) {
    throw new Error(
      `Catálogo ambiguo para el código ${codigoExcel}. Hay más de un producto posible para ${clienteGrupo} / ${plantaCodigo} / ${subplantaCodigo}.`
    );
  }

  return null;
}

function buscarCliente(clientesMap, contexto) {
  const clienteGrupo = contexto.cliente_grupo;
  const plantaCodigo = contexto.planta_codigo;
  const subplantaCodigo = contexto.subplanta_codigo || "";

  const keys = [
    makeKey(clienteGrupo, plantaCodigo, subplantaCodigo),
    makeKeyRaw(clienteGrupo, plantaCodigo, subplantaCodigo),

    makeKey(clienteGrupo, plantaCodigo, ""),
    makeKeyRaw(clienteGrupo, plantaCodigo, "")
  ];

  const exacto = buscarEnMapa(clientesMap, keys);

  if (exacto) return exacto;

  const candidatos = objectValuesSafe(clientesMap).filter(cliente => {
    const mismoCliente =
      normalizeText(cliente.cliente_grupo) === normalizeText(clienteGrupo);

    const mismaPlanta =
      normalizeText(cliente.planta_codigo) === normalizeText(plantaCodigo);

    const subCliente = normalizeText(cliente.subplanta_codigo || "");
    const subContexto = normalizeText(subplantaCodigo || "");

    const mismaSubplanta =
      subContexto === "" ||
      subCliente === subContexto ||
      subCliente === "";

    return mismoCliente && mismaPlanta && mismaSubplanta;
  });

  if (candidatos.length === 1) return candidatos[0];

  if (candidatos.length > 1) {
    const conSubplanta = candidatos.find(cliente =>
      normalizeText(cliente.subplanta_codigo || "") === normalizeText(subplantaCodigo || "")
    );

    if (conSubplanta) return conSubplanta;
  }

  return null;
}

