function cleanText(value) {
  return String(value ?? "")
    .replace(/\t/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function normalize(value) {
  return cleanText(value)
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toUpperCase();
}

function get(row, names) {
  for (const name of names) {
    if (
      row[name] !== undefined &&
      row[name] !== null &&
      String(row[name]).trim() !== ""
    ) {
      return row[name];
    }
  }

  return "";
}

function makeKey(clienteGrupo, plantaCodigo, subplantaCodigo, codigoExcel) {
  return [
    normalize(clienteGrupo),
    normalize(plantaCodigo),
    normalize(subplantaCodigo),
    normalize(codigoExcel)
  ].join("|");
}

function addIfNotEmpty(object, key, value) {
  const text = cleanText(value);

  if (text !== "") {
    object[key] = text;
  }
}

const productosMap = {};
const duplicados = [];
const omitidos = [];

for (const item of $input.all()) {
  const row = item.json;

  const activo = normalize(get(row, [
    "activo",
    "Activo"
  ]));

  const clienteGrupo = get(row, [
    "cliente_grupo",
    "Cliente Grupo",
    "cliente"
  ]);

  const plantaCodigo = get(row, [
    "planta_codigo",
    "Planta",
    "planta"
  ]);

  const subplantaCodigo = get(row, [
    "subplanta_codigo",
    "Subplanta",
    "subplanta"
  ]);

  const codigoExcel = get(row, [
    "codigo_excel",
    "Código",
    "Codigo",
    "codigo"
  ]);

  if (activo && activo !== "SI") {
    continue;
  }

  if (!clienteGrupo || !plantaCodigo || !codigoExcel) {
    omitidos.push({
      motivo: "Falta cliente_grupo, planta_codigo o codigo_excel",
      row
    });

    continue;
  }

  const key = makeKey(
    clienteGrupo,
    plantaCodigo,
    subplantaCodigo,
    codigoExcel
  );

  if (productosMap[key]) {
    duplicados.push(key);
  }

  const producto = {
    key,

    activo: "SI",

    cliente_grupo: cleanText(clienteGrupo),
    planta_codigo: cleanText(plantaCodigo),
    subplanta_codigo: cleanText(subplantaCodigo),

    codigo_excel: normalize(codigoExcel),

    numero_parte: cleanText(get(row, [
      "numero_parte",
      "Número de parte",
      "Numero de parte",
      "No. parte",
      "no_parte"
    ])),

    descripcion_catalogo: cleanText(get(row, [
      "descripcion_catalogo",
      "Descripción",
      "Descripcion",
      "descripcion"
    ])),

    unidad_remision: normalize(get(row, [
      "unidad_remision",
      "Unidad remisión",
      "Unidad remision",
      "unidad"
    ])),

    tipo_empaque: normalize(get(row, [
      "tipo_empaque",
      "Tipo empaque",
      "Tipo de empaque"
    ])),

    cantidad_por_empaque: cleanText(get(row, [
      "cantidad_por_empaque",
      "Cantidad por empaque"
    ])),

    observaciones: cleanText(get(row, [
      "observaciones",
      "Observaciones"
    ])),

    llave_producto: cleanText(get(row, [
      "llave_producto",
      "Llave producto",
      "llave"
    ])),

    estado_validacion: normalize(get(row, [
      "estado_validacion",
      "Estado validación",
      "Estado validacion"
    ]))
  };

  // Opcionales: solo aparecen si existen en el catálogo.
  // Útiles si después los agregas para Torreón.
  addIfNotEmpty(producto, "precio_unitario_usd", get(row, [
    "precio_unitario_usd",
    "precio_unitario",
    "precio_usd",
    "precio"
  ]));

  addIfNotEmpty(producto, "unidad_torreon", get(row, [
    "unidad_torreon",
    "unidad_cfdi",
    "unidad_sat"
  ]));

  addIfNotEmpty(producto, "moneda", get(row, [
    "moneda",
    "Moneda"
  ]));

  addIfNotEmpty(producto, "tipo_cambio_default", get(row, [
    "tipo_cambio_default",
    "tipo_cambio",
    "Tipo de cambio",
    "TC",
    "T.C."
  ]));

  productosMap[key] = producto;
}

return [
  {
    json: {
      productos_map: productosMap,
      productos_total: Object.keys(productosMap).length,
      productos_duplicados: duplicados,
      productos_omitidos: omitidos
    }
  }
];

