function detectarFinsa(fileNameNorm) {
  const match = fileNameNorm.match(/FINSA\s*(\d+)/);

  if (!match) {
    return {
      subplantaCodigo: "",
      procesar: false,
      motivo: "No se detectó FINSA 1 / FINSA 3"
    };
  }

  const numeroFinsa = Number(match[1]);

  if (![1, 3].includes(numeroFinsa)) {
    return {
      subplantaCodigo: `FINSA_${numeroFinsa}`,
      procesar: false,
      motivo: `FINSA detectada no permitida: FINSA_${numeroFinsa}`
    };
  }

  return {
    subplantaCodigo: `FINSA_${numeroFinsa}`,
    procesar: true,
    motivo: "Archivo válido"
  };
}

function detectarP3P6(fileNameNorm) {
  // Caso especial: SC PLANTA 3 pertenece a P3
  if (
    fileNameNorm.includes("SC PLANTA 3") ||
    fileNameNorm.includes("SC PL 3")
  ) {
    return {
      plantaCodigo: "P3",
      procesar: true,
      motivo: "Archivo válido"
    };
  }

  const match = fileNameNorm.match(/\b(?:PLANTA|PL)\s*(\d+)\b/);

  if (!match) {
    return {
      plantaCodigo: "MULTIPLANTA",
      procesar: false,
      motivo: "No se detectó PLANTA / PL 3, 4, 5 o 6"
    };
  }

  const numeroPlanta = Number(match[1]);
  const plantaCodigo = `P${numeroPlanta}`;

  if (!["P3", "P4", "P5", "P6"].includes(plantaCodigo)) {
    return {
      plantaCodigo,
      procesar: false,
      motivo: `La planta detectada no está permitida: ${plantaCodigo}`
    };
  }

  return {
    plantaCodigo,
    procesar: true,
    motivo: "Archivo válido"
  };
}

function detectarTorreon(fileNameNorm) {
  const match = fileNameNorm.match(/\bPLANTA\s*(\d+)\b/);

  if (!match) {
    return {
      subplantaCodigo: "",
      procesar: true,
      motivo: "Archivo válido"
    };
  }

  const numeroPlanta = Number(match[1]);

  return {
    subplantaCodigo: `PLANTA_${numeroPlanta}`,
    procesar: true,
    motivo: "Archivo válido"
  };
}

