const resultados = [];
const commonPaths = buildCommonPaths();

for (const cfg of RUTAS) {
  const inputDirs = getInputDirs(cfg);

  if (inputDirs.length === 0) {
    resultados.push({
      tipo_resultado: "CONFIGURACION_INVALIDA",

      cliente_grupo: cfg.cliente_grupo,
      nombre_planta: cfg.nombre_planta,
      planta_codigo: cfg.planta_default,
      subplanta_codigo: "",
      llave_proceso: `${cfg.cliente_grupo}|${cfg.planta_default}|`,

      file_name: "",
      source_base_name: "",
      file_path: "",
      file_key: "",
      file_size_bytes: 0,

      carpeta_revision: "",
      ruta_base: cleanText(cfg.base_ruta_anual || cfg.ruta),
      usa_anio: Boolean(cfg.usa_anio),
      anio_operacion: "",

      carpeta_salida_pruebas: buildOutputFolder(
        cfg.cliente_grupo,
        cfg.planta_default,
        ""
      ),

      fecha_archivo_iso: "",
      fecha_archivo_timestamp: 0,

      last_write_time: "",
      last_write_time_utc: "",

      tipo_documento: cfg.tipo_documento,
      modo_deteccion: cfg.modo_deteccion,
      procesar_automaticamente: false,
      motivo: "Configuración inválida: no se pudo construir carpeta de revisión",

      anio_actual: ANIO_ACTUAL,
      mes_actual: MES_ACTUAL,
      anios_a_escanear: ANIOS_A_ESCANEAR.join(","),

      ...commonPaths
    });

    continue;
  }

  for (const dirInfo of inputDirs) {
    const rutaRevision = dirInfo.input_dir;

    if (!fs.existsSync(rutaRevision)) {
      resultados.push({
        tipo_resultado: "CARPETA_NO_EXISTE",

        cliente_grupo: cfg.cliente_grupo,
        nombre_planta: cfg.nombre_planta,
        planta_codigo: cfg.planta_default,
        subplanta_codigo: "",
        llave_proceso: `${cfg.cliente_grupo}|${cfg.planta_default}|`,

        file_name: "",
        source_base_name: "",
        file_path: "",
        file_key: "",
        file_size_bytes: 0,

        carpeta_revision: rutaRevision,
        ruta_base: dirInfo.ruta_base,
        usa_anio: dirInfo.usa_anio,
        anio_operacion: dirInfo.anio_operacion,

        carpeta_salida_pruebas: buildOutputFolder(
          cfg.cliente_grupo,
          cfg.planta_default,
          ""
        ),

        fecha_archivo_iso: "",
        fecha_archivo_timestamp: 0,

        last_write_time: "",
        last_write_time_utc: "",

        tipo_documento: cfg.tipo_documento,
        modo_deteccion: cfg.modo_deteccion,
        procesar_automaticamente: false,
        motivo: "La carpeta configurada no existe",

        anio_actual: ANIO_ACTUAL,
        mes_actual: MES_ACTUAL,
        anios_a_escanear: ANIOS_A_ESCANEAR.join(","),

        ...commonPaths
      });

      continue;
    }

    const archivos = fs
      .readdirSync(rutaRevision, { withFileTypes: true })
      .filter(entry => entry.isFile())
      .map(entry => {
        const fullPath = path.join(rutaRevision, entry.name);
        const stat = fs.statSync(fullPath);

        return {
          name: entry.name,
          fullPath,
          stat
        };
      });

    for (const archivo of archivos) {
      const fileName = archivo.name;
      const fileNameNorm = normalizeText(fileName);
      const patronNorm = normalizeText(cfg.patron);

      if (fileName.startsWith("~$")) continue;
      if (!isExcelFile(fileName)) continue;
      if (!fileNameNorm.includes(patronNorm)) continue;

      let clienteGrupo = cfg.cliente_grupo;
      let nombrePlanta = cfg.nombre_planta;
      let plantaCodigo = cfg.planta_default;
      let subplantaCodigo = "";
      let procesar = Boolean(cfg.procesar_automaticamente);
      let motivo = "Archivo válido";

      // =====================================================
      // MODO PRUEBA LOCAL: 00_ARCHIVOS A PROCESAR
      // =====================================================
      if (cfg.modo_deteccion === "PRUEBA_LOCAL") {
        const detectado = detectarPruebaLocal(fileNameNorm);

        clienteGrupo = detectado.clienteGrupo;
        nombrePlanta = detectado.nombrePlanta;
        plantaCodigo = detectado.plantaCodigo;
        subplantaCodigo = detectado.subplantaCodigo;
        procesar = detectado.procesar;
        motivo = detectado.motivo;
      }

      // =====================================================
      // MODO FIJO: P2
      // =====================================================
      if (cfg.modo_deteccion === "FIJO") {
        plantaCodigo = cfg.planta_default;
        subplantaCodigo = "";
        procesar = Boolean(cfg.procesar_automaticamente);
        motivo = "Archivo válido";
      }

      // =====================================================
      // MODO FINSA: Nuevo Laredo
      // =====================================================
      if (cfg.modo_deteccion === "FINSA") {
        const detectado = detectarFinsa(fileNameNorm);

        plantaCodigo = cfg.planta_default;
        subplantaCodigo = detectado.subplantaCodigo;
        procesar = detectado.procesar;
        motivo = detectado.motivo;
      }

      // =====================================================
      // MODO P3/P4/P5/P6
      // =====================================================
      if (cfg.modo_deteccion === "P3P6") {
        const detectado = detectarP3P6(fileNameNorm);

        plantaCodigo = detectado.plantaCodigo;
        subplantaCodigo = "";
        procesar = detectado.procesar;
        motivo = detectado.motivo;
      }

      // =====================================================
      // MODO TORREÓN
      // =====================================================
      if (cfg.modo_deteccion === "TORREON") {
        const detectado = detectarTorreon(fileNameNorm);

        plantaCodigo = cfg.planta_default;
        subplantaCodigo = detectado.subplantaCodigo;
        procesar = detectado.procesar;
        motivo = detectado.motivo;
      }

      // =====================================================
      // MODO LEGACY
      // =====================================================
      if (cfg.modo_deteccion === "LEGACY") {
        plantaCodigo = cfg.planta_default;
        subplantaCodigo = "";
        procesar = false;
        motivo = "Documento legacy detectado; no procesar automáticamente";
      }

      const fechaArchivo = getDateFromFileName(
        fileName,
        archivo.stat.mtime
      );

      const carpetaSalidaPruebas = buildOutputFolder(
        clienteGrupo,
        plantaCodigo,
        subplantaCodigo
      );

      const llaveProceso =
        `${clienteGrupo}|${plantaCodigo}|${subplantaCodigo}`;

      const fileKey = [
        archivo.fullPath,
        archivo.stat.size,
        archivo.stat.mtime.toISOString()
      ].join("|");

      const sourceBaseName = fileName.replace(/\.[^.]+$/i, "");

      resultados.push({
        tipo_resultado: "ARCHIVO_DETECTADO",

        cliente_grupo: clienteGrupo,
        nombre_planta: nombrePlanta,

        planta_codigo: plantaCodigo,
        subplanta_codigo: subplantaCodigo,
        llave_proceso: llaveProceso,

        file_name: fileName,
        source_base_name: sourceBaseName,
        file_path: archivo.fullPath,
        file_key: fileKey,
        file_size_bytes: archivo.stat.size,

        carpeta_revision: rutaRevision,
        ruta_base: dirInfo.ruta_base,
        usa_anio: dirInfo.usa_anio,
        anio_operacion: dirInfo.anio_operacion,

        carpeta_salida_pruebas: carpetaSalidaPruebas,

        fecha_archivo_iso: toIsoDate(fechaArchivo),
        fecha_archivo_timestamp: toUnixTimestamp(fechaArchivo),

        last_write_time: archivo.stat.mtime.toISOString(),
        last_write_time_utc: archivo.stat.mtime.toISOString(),

        tipo_documento: cfg.tipo_documento,
        modo_deteccion: cfg.modo_deteccion,
        procesar_automaticamente: procesar,
        motivo,

        anio_actual: ANIO_ACTUAL,
        mes_actual: MES_ACTUAL,
        anios_a_escanear: ANIOS_A_ESCANEAR.join(","),

        ...commonPaths
      });
    }
  }
