function cleanText(value) {
  return String(value ?? "").trim();
}

function normalizeText(value) {
  return cleanText(value)
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toUpperCase()
    .replace(/\s+/g, " ")
    .trim();
}

function isExcelFile(fileName) {
  const name = cleanText(fileName).toLowerCase();

  return (
    name.endsWith(".xlsx") ||
    name.endsWith(".xlsm") ||
    name.endsWith(".xls")
  );
}

function getDateFromFileName(fileName, lastWriteTime) {
  const name = cleanText(fileName);

  const matches8 = name.match(/\d{8}/g);

  if (matches8 && matches8.length > 0) {
    const raw = matches8[matches8.length - 1];

    const year = Number(raw.slice(0, 4));
    const month = Number(raw.slice(4, 6));
    const day = Number(raw.slice(6, 8));

    const date = new Date(Date.UTC(year, month - 1, day));

    if (
      !isNaN(date.getTime()) &&
      year >= 2020 &&
      month >= 1 &&
      month <= 12 &&
      day >= 1 &&
      day <= 31
    ) {
      return date;
    }
  }

  const matches6 = name.match(/\d{6}/g);

  if (matches6 && matches6.length > 0) {
    const raw = matches6[matches6.length - 1];

    const year = 2000 + Number(raw.slice(0, 2));
    const month = Number(raw.slice(2, 4));
    const day = Number(raw.slice(4, 6));

    const date = new Date(Date.UTC(year, month - 1, day));

    if (
      !isNaN(date.getTime()) &&
      year >= 2020 &&
      month >= 1 &&
      month <= 12 &&
      day >= 1 &&
      day <= 31
    ) {
      return date;
    }
  }

  return lastWriteTime;
}

function toIsoDate(date) {
  if (!(date instanceof Date) || isNaN(date.getTime())) return "";

  const year = date.getUTCFullYear();
  const month = String(date.getUTCMonth() + 1).padStart(2, "0");
  const day = String(date.getUTCDate()).padStart(2, "0");

  return `${year}-${month}-${day}`;
}

function toUnixTimestamp(date) {
  if (!(date instanceof Date) || isNaN(date.getTime())) return 0;
  return Math.floor(date.getTime() / 1000);
}

function buildOutputFolder(clienteGrupo, plantaCodigo, subplantaCodigo) {
  let folder = path.join(OUTPUT_DIR, clienteGrupo);

  if (
    clienteGrupo === "CAT_P3_P4_P5_P6" &&
    plantaCodigo &&
    plantaCodigo !== "MULTIPLANTA"
  ) {
    folder = path.join(folder, plantaCodigo);
  }

  if (clienteGrupo === "CAT_NUEVO_LAREDO" && subplantaCodigo) {
    folder = path.join(folder, subplantaCodigo);
  }

  if (clienteGrupo === "CAT_TORREON" && subplantaCodigo) {
    folder = path.join(folder, subplantaCodigo);
  }

  return folder;
}

function detectarFinsa(fileNameNorm) {
  const match = fileNameNorm.match(/FINSA\s*(\d+)/);

  if (!match) {
    return {
      subplantaCodigo: "",
      procesar: false,
      motivo: "No se detecto FINSA 1 / FINSA 3"
    };
  }

  const numeroFinsa = Number(match[1]);

  if (![1, 3].includes(numeroFinsa)) {
    return {
      subplantaCodigo: `FINSA_${numeroFinsa}`,
      procesar: false,
      motivo: `FINSA detectada no permitida: FINSA_${numeroFinsa}`
    };
  }

  return {
    subplantaCodigo: `FINSA_${numeroFinsa}`,
    procesar: true,
    motivo: "Archivo valido"
  };
}

function detectarP3P6(fileNameNorm) {
  if (
    fileNameNorm.includes("SC PLANTA 3") ||
    fileNameNorm.includes("SC PL 3")
  ) {
    return {
      plantaCodigo: "P3",
      procesar: true,
      motivo: "Archivo valido"
    };
  }

  const match = fileNameNorm.match(/\b(?:PLANTA|PL)\s*(\d+)\b/);

  if (!match) {
    return {
      plantaCodigo: "MULTIPLANTA",
      procesar: false,
      motivo: "No se detecto PLANTA / PL 3, 4, 5 o 6"
    };
  }

  const numeroPlanta = Number(match[1]);
  const plantaCodigo = `P${numeroPlanta}`;

  if (!["P3", "P4", "P5", "P6"].includes(plantaCodigo)) {
    return {
      plantaCodigo,
      procesar: false,
      motivo: `La planta detectada no esta permitida: ${plantaCodigo}`
    };
  }

  return {
    plantaCodigo,
    procesar: true,
    motivo: "Archivo valido"
  };
}

function detectarTorreon(fileNameNorm) {
  const match = fileNameNorm.match(/\bPLANTA\s*(\d+)\b/);

  if (!match) {
    return {
      subplantaCodigo: "",
      procesar: true,
      motivo: "Archivo valido"
    };
  }

  const numeroPlanta = Number(match[1]);

  return {
    subplantaCodigo: `PLANTA_${numeroPlanta}`,
    procesar: true,
    motivo: "Archivo valido"
  };
}

function detectarPruebaLocal(fileNameNorm) {
  if (
    fileNameNorm.includes("TORREON") ||
    fileNameNorm.includes("TORREÓN")
  ) {
    const detectado = detectarTorreon(fileNameNorm);

    return {
      clienteGrupo: "CAT_TORREON",
      nombrePlanta: "CAT TORREON",
      plantaCodigo: "TORREON",
      subplantaCodigo: detectado.subplantaCodigo,
      procesar: detectado.procesar,
      motivo: `Archivo de prueba valido - CAT_TORREON${detectado.subplantaCodigo ? " - " + detectado.subplantaCodigo : ""}`
    };
  }

  if (fileNameNorm.includes("FINSA")) {
    const detectado = detectarFinsa(fileNameNorm);

    return {
      clienteGrupo: "CAT_NUEVO_LAREDO",
      nombrePlanta: "CAT NUEVO LAREDO",
      plantaCodigo: "NUEVO_LAREDO",
      subplantaCodigo: detectado.subplantaCodigo,
      procesar: detectado.procesar,
      motivo: detectado.procesar
        ? `Archivo de prueba valido - CAT_NUEVO_LAREDO - ${detectado.subplantaCodigo}`
        : detectado.motivo
    };
  }

  if (
    fileNameNorm.includes("SC PLANTA 2") ||
    fileNameNorm.includes("SC PL 2") ||
    fileNameNorm.includes("CATERPILLAR P2") ||
    fileNameNorm.includes("CAT P2") ||
    /\bP2\b/.test(fileNameNorm)
  ) {
    return {
      clienteGrupo: "CATERPILLAR_P2",
      nombrePlanta: "CATERPILLAR MEXICO - P2",
      plantaCodigo: "P2",
      subplantaCodigo: "",
      procesar: true,
      motivo: "Archivo de prueba valido - CATERPILLAR_P2 - P2"
    };
  }

  if (
    fileNameNorm.includes("PLANTA 3") ||
    fileNameNorm.includes("PLANTA 4") ||
    fileNameNorm.includes("PLANTA 5") ||
    fileNameNorm.includes("PLANTA 6") ||
    fileNameNorm.includes("PL 3") ||
    fileNameNorm.includes("PL 4") ||
    fileNameNorm.includes("PL 5") ||
    fileNameNorm.includes("PL 6") ||
    /\bP3\b/.test(fileNameNorm) ||
    /\bP4\b/.test(fileNameNorm) ||
    /\bP5\b/.test(fileNameNorm) ||
    /\bP6\b/.test(fileNameNorm)
  ) {
    const detectado = detectarP3P6(fileNameNorm);

    return {
      clienteGrupo: "CAT_P3_P4_P5_P6",
      nombrePlanta: "CATERPILLAR INDUSTRIAS MEXICO - P3 P4 P5 P6",
      plantaCodigo: detectado.plantaCodigo,
      subplantaCodigo: "",
      procesar: detectado.procesar,
      motivo: detectado.procesar
        ? `Archivo de prueba valido - CAT_P3_P4_P5_P6 - ${detectado.plantaCodigo}`
        : detectado.motivo
    };
  }

  return {
    clienteGrupo: "PRUEBA_LOCAL",
    nombrePlanta: "PRUEBA LOCAL - NO CLASIFICADA",
    plantaCodigo: "NO_CLASIFICADA",
    subplantaCodigo: "",
    procesar: false,
    motivo: "Archivo de prueba detectado, pero no se pudo clasificar cliente/planta desde el nombre"
  };
}

